window.BANGLADESH = {"workshops":[{"id":"institutions","code":"A3519987","short":"Tripartite institutions","title":"Strengthening Tripartite Social Dialogue Institutions: From Policy Design to Effective Implementation and Institutional Transformation","dates":"26–29 October 2026","start":"2026-10-26","duration":3.5,"participants":"Members of tripartite social dialogue institutions and staff of their secretariats","outputs":"Draft policy proposals and institutional action plans setting out objectives, responsibilities, timelines, coordination arrangements and monitoring mechanisms","agenda":"downloads/A3519987/A3519987_Agenda_Rev.1.docx","days":[{"number":1,"date":"2026-10-26","label":"Day one — Monday, 26 October 2026","theme":"Tripartite social dialogue institutions and their role in policy-making","items":[{"time":"08:30 – 09:00","title":"Registration, distribution of materials and welcome refreshments"},{"time":"09:00 – 10:30","title":"Opening, course objectives and the role of tripartite social dialogue institutions in policy-making","session":1,"id":"A3519987-s1","topics":["Welcome, introductions and review of the preparation phase","Social dialogue and tripartism: forms, preconditions and the relevant International Labour Standards, including Conventions Nos. 87, 98 and 144","What tripartite institutions contribute at each stage of the policy cycle: agenda setting, formulation, decision, implementation, monitoring and evaluation","Opening exercise: what works, and what blocks, in our own institutions"],"handouts":["A3519987-h1"]},{"time":"10:30 – 11:00","title":"Morning refreshment break"},{"time":"11:00 – 12:30","title":"Mapping the tripartite social dialogue architecture of Bangladesh","session":2,"id":"A3519987-s2","topics":["Mandates, composition, quorum and decision-making of the National Tripartite Consultative Council and of the newly constituted National Social Dialogue Forum (established by notification dated 10 August 2026, published in the Bangladesh Gazette on 13 August 2026 under section 348(B) of the Bangladesh Labour (Amendment) Act, 2026)","Sectoral and thematic tripartite bodies and their relationship to the national level","Where mandates overlap, where they are silent, and where decisions are lost between bodies","Group exercise: institutional mapping of the national, sectoral and thematic tripartite landscape"],"handouts":["A3519987-h2"]},{"time":"12:30 – 13:30","title":"Lunch"},{"time":"13:30 – 15:00","title":"Coordination, complementarity and synergies among tripartite bodies: the NTCC and the National Social Dialogue Forum","session":3,"id":"A3519987-s3","topics":["The terms of reference of the National Social Dialogue Forum and its mandate to ensure coordination with the NTCC, sector-based tripartite institutions and other tripartite social dialogue institutions","Avoiding duplication, forum shopping and conflicting recommendations between bodies with close but distinct mandates","Information flow, joint agenda setting, referral and reporting between institutions","Group exercise: drafting a working protocol on the division of labour and referral between the Forum and the NTCC"],"handouts":["A3519987-h3"]},{"time":"15:00 – 15:30","title":"Afternoon refreshment break"},{"time":"15:30 – 16:30","title":"Comparative experience: organizing national social dialogue architecture","session":4,"id":"A3519987-s4","topics":["Economic and social councils and national dialogue bodies: legal basis, structure, secretariat and relationship with sectoral institutions","Experience from the region and beyond, including the National Economic Development and Labour Council of South Africa","Plenary discussion: what is transferable to Bangladesh, and under what conditions"],"handouts":["A3519987-h4"]}]},{"number":2,"date":"2026-10-27","label":"Day two — Tuesday, 27 October 2026","theme":"Evidence, inclusion and representation in policy design","items":[{"time":"09:00 – 10:30","title":"Evidence-based policy design: from data to policy options","session":5,"id":"A3519987-s5","topics":["Sources of labour market evidence in Bangladesh and how to assess their credibility and currency","Turning evidence into neutral, costed policy options that a tripartite body can decide on","Group exercise: building a policy options note from a mixed evidence pack"],"handouts":["A3519987-h5"]},{"time":"10:30 – 11:00","title":"Morning refreshment break"},{"time":"11:00 – 12:30","title":"Gender-responsive and inclusive policy design","session":6,"id":"A3519987-s6","topics":["Applying gender analysis at each stage of the policy cycle","Representation of women in tripartite bodies, and in the issues those bodies take up","Group exercise: gender-responsiveness audit of a draft policy proposal"],"handouts":["A3519987-h6"]},{"time":"12:30 – 13:30","title":"Lunch"},{"time":"13:30 – 15:00","title":"Informality, representation and inclusive participation","session":7,"id":"A3519987-s7","topics":["Building effective social dialogue foundations and mechanisms in a context of high informality","Representation of workers and economic units in the informal economy; ILO Recommendation No. 204 on the transition from the informal to the formal economy","Group exercise: diagnosing representation gaps in our own institutions"],"handouts":["A3519987-h7"]},{"time":"15:00 – 15:30","title":"Afternoon refreshment break"},{"time":"15:30 – 16:30","title":"Practical mechanisms for widening participation","session":8,"id":"A3519987-s8","topics":["Sub-committees, observer status, consultative panels and thematic working groups","Widening participation while safeguarding the integrity and representativeness of tripartism","Group exercise: designing an inclusion mechanism for one national or sectoral body"],"handouts":["A3519987-h8"]}]},{"number":3,"date":"2026-10-28","label":"Day three — Wednesday, 28 October 2026","theme":"From dialogue to delivery: implementation, monitoring and institutional change","items":[{"time":"09:00 – 10:30","title":"Translating social dialogue outcomes into implementation frameworks","session":9,"id":"A3519987-s9","topics":["From agreed conclusions to assigned, costed and time-bound commitments","Implementation arrangements: responsibilities, timelines, coordination mechanisms and resourcing","Group exercise: converting a set of tripartite conclusions into an implementation framework"],"handouts":["A3519987-h9"]},{"time":"10:30 – 11:00","title":"Morning refreshment break"},{"time":"11:00 – 12:30","title":"Monitoring, evaluation and follow-up of tripartite decisions","session":10,"id":"A3519987-s10","topics":["Tracking implementation across ministries and social partners; the register of conclusions and the tabling method","Simple indicators of institutional performance, including gender and inclusion indicators","Group exercise: building a resolution implementation matrix for a national or sectoral body"],"handouts":["A3519987-h10"]},{"time":"12:30 – 13:30","title":"Lunch"},{"time":"13:30 – 15:00","title":"Institutional change and reform processes","session":11,"id":"A3519987-s11","topics":["Diagnosing underperformance: mandate, capacity, resources, procedure or political space","Sequencing reform; what can be changed through practice and what requires legal amendment","Group exercise: institutional change diagnostic and reform pathway"],"handouts":["A3519987-h11"]},{"time":"15:00 – 15:30","title":"Afternoon refreshment break"},{"time":"15:30 – 16:30","title":"Working groups: policy proposals and institutional action plans (part one)","session":12,"id":"A3519987-s12","topics":["Groups form around the priority themes agreed in plenary","Drafting begins: objective, legal basis, responsible institution, timeline, coordination arrangements and indicators"],"handouts":["A3519987-h12"]}]},{"number":4,"date":"2026-10-29","label":"Day four — Thursday, 29 October 2026 (half day)","theme":"Consolidation and way forward","items":[{"time":"09:00 – 10:30","title":"Working groups: policy proposals and institutional action plans (part two)","session":13,"id":"A3519987-s13","topics":["Completion of the draft proposals and action plans","Structured peer review between groups against feasibility, cost and institutional mandate"],"handouts":["A3519987-h13"]},{"time":"10:30 – 11:00","title":"Morning refreshment break"},{"time":"11:00 – 12:30","title":"Plenary presentation, consolidation and way forward","session":14,"id":"A3519987-s14","topics":["Presentation of the group proposals and institutional action plans","Tripartite feedback and agreement on follow-up, including coordination between the National Social Dialogue Forum, the NTCC and sectoral bodies","Course evaluation"],"handouts":["A3519987-h14"]},{"time":"12:30","title":"Close of the course phase"}]}],"pack":"downloads/A3519987/A3519987_Participant_Handouts_Rev1.zip"},{"id":"secretariats","code":"A3519988","short":"Secretariat capacities","title":"Strengthening the Capacities of the Secretariats of Tripartite Social Dialogue Institutions in Bangladesh","dates":"30 October–1 November 2026","start":"2026-10-30","duration":2.5,"participants":"Secretariat and support staff of tripartite social dialogue institutions in Bangladesh","outputs":"An individual 30-day plan of priority improvements and a three-month institutional roadmap for each secretariat, together with draft operating protocols on neutrality, documentation, budgeting and follow-up","agenda":"downloads/A3519988/A3519988_Agenda_Rev.1.docx","days":[{"number":1,"date":"2026-10-30","label":"Day one — Friday, 30 October 2026","theme":"Foundations of tripartite social dialogue and institutional governance","items":[{"time":"08:30 – 09:00","title":"Registration, distribution of the secretariat toolkit and welcome refreshments"},{"time":"09:00 – 10:30","title":"Opening and introduction · Module 1: Social dialogue, tripartism and national tripartite social dialogue","session":1,"id":"A3519988-s1","topics":["Welcome, course objectives, timetable and working agreement; review of the preparation phase","Self-assessment of secretariat competencies and participant introductions","Forms of social dialogue: information sharing, consultation and negotiation; bipartite and tripartite processes","The enabling legal instruments for national tripartite social dialogue in Bangladesh, including the NTCC and the newly constituted National Social Dialogue Forum","Paired exercise: the preconditions for effective national tripartite social dialogue in Bangladesh"],"handouts":["A3519988-h1"]},{"time":"10:30 – 11:00","title":"Morning refreshment break"},{"time":"11:00 – 12:30","title":"Module 2: Roles and responsibilities — the secretariat as the operational core","session":2,"id":"A3519988-s2","topics":["Roles and responsibilities of government and of employers’ and workers’ organizations","Purpose, authority and functions of the secretariat as a neutral facilitator and support structure, with reference to Bangladesh and comparative models","Key competencies and skills; managing multi-stakeholder relationships","Group exercise: conduct and ethics scenarios, and agreeing minimum standards of conduct"],"handouts":["A3519988-h2"]},{"time":"12:30 – 13:30","title":"Lunch"},{"time":"13:30 – 15:00","title":"Module 3: Planning and organizing meetings","session":3,"id":"A3519988-s3","topics":["Protocols for tabling matters and reaching outcomes: certainty, consistency and predictability","Agenda setting and notice: consultation, a clear purpose for each item, advance circulation of working documents","Venue, resources and logistics","Role play: preparing the agenda and notice for a tripartite meeting"],"handouts":["A3519988-h3"]},{"time":"15:00 – 15:30","title":"Afternoon refreshment break"},{"time":"15:30 – 16:30","title":"Module 4: Documentation and record-keeping","session":4,"id":"A3519988-s4","topics":["Types of secretariat documents; styles and structure of minutes; recording disagreement honestly and in gender-neutral terms","Resolutions and action sheets: the bridge from minutes to action","Filing, archiving, confidentiality and institutional memory","Drill: auditing and correcting a draft set of minutes"],"handouts":["A3519988-h4"]}]},{"number":2,"date":"2026-10-31","label":"Day two — Saturday, 31 October 2026","theme":"Operational effectiveness of secretariats","items":[{"time":"09:00 – 10:30","title":"Module 5: Communication, facilitation and stakeholder engagement","session":5,"id":"A3519988-s5","topics":["Listening skills, non-verbal communication and the use of first-person statements to reduce blame","Reframing charged statements; empathy combined with independence","Group exercise: redrafting formal communication so that it is clear, concise and neutral"],"handouts":["A3519988-h5"]},{"time":"10:30 – 11:00","title":"Morning refreshment break"},{"time":"11:00 – 12:30","title":"Module 6: Protocol and administrative support","session":6,"id":"A3519988-s6","topics":["Seating protocol, agenda terminology, handling private approaches and ensuring equal access to documents","Managing official correspondence; electronic administration and data security; the inclusiveness protocol","Activity 1: the neutrality test — four protocol dilemmas in a minimum wage negotiation","Activity 2: designing a standard operating procedure for information equity"],"handouts":["A3519988-h6"]},{"time":"12:30 – 13:30","title":"Lunch"},{"time":"13:30 – 15:00","title":"Module 7: Financial management and budgeting","session":7,"id":"A3519988-s7","topics":["Budget preparation and expenditure lines; the link between financial autonomy and secretariat independence","Procurement rules, allowances and audit discipline","Activity 1: the annual budget negotiation under a ceiling of 10 per cent","Activity 2: the transparency and audit crisis"],"handouts":["A3519988-h6"]},{"time":"15:00 – 15:30","title":"Afternoon refreshment break"},{"time":"15:30 – 16:30","title":"Module 8: Providing technical and policy support","session":8,"id":"A3519988-s8","topics":["Distinguishing administrative duties from technical support functions; the proactive secretariat","Sources of technical information in Bangladesh; briefing notes and presenting technical data in accessible terms","Activity 1: the briefing note challenge — drafting for neutrality","Activity 2: the data credibility check"],"handouts":["A3519988-h6"]}]},{"number":3,"date":"2026-11-01","label":"Day three — Sunday, 1 November 2026 (half day)","theme":"Strategic support, monitoring and institutional learning","items":[{"time":"09:00 – 10:30","title":"Module 9: Monitoring, evaluation and follow-up","session":9,"id":"A3519988-s9","topics":["Converting minutes into an actionable plan; the tabling method and the register of conclusions","Indicators of institutional health, including gender and inclusion indicators","Activity 1: the tabling method and the action sheet","Activity 2: designing a monitoring and evaluation framework for institutional effectiveness"],"handouts":["A3519988-h6"]},{"time":"10:30 – 11:00","title":"Morning refreshment break"},{"time":"11:00 – 12:30","title":"Modules 10 and 11: Strengthening institutional capacity and action planning","session":10,"id":"A3519988-s10","topics":["The ideal secretariat structure and staffing profile; dedicated budget, knowledge management and continuity when staff rotate","Institutional risk: loss of institutional memory, loss of digital records and external pressure on neutrality","Action planning: three priority improvements for the first 30 days and a three-month institutional roadmap","Course evaluation"],"handouts":["A3519988-h6"]},{"time":"12:30","title":"Close of the course phase"}]}],"pack":"downloads/A3519988/A3519988_Participant_Handouts_Rev1.zip"}],"activities":[{"id":"A3519987-h1","workshop":"institutions","code":"A3519987","number":1,"title":"What works, and what blocks","file":"downloads/A3519987/A3519987_H1.1_What_works_and_what_blocks.docx","html":"<p>PARTICIPANT HANDOUT 1.1</p><p>What works, and what blocks</p><p>Session 1 — Day one, 09:00–10:30   ·   12 minutes   ·   Mixed tripartite groups of five or six</p><div class=\"table-scroll\"><table><tr><th>TASK    Identify what your institution genuinely does well, and the single biggest thing that blocks it from contributing to policy.</th></tr></table></div><p>1.  Each person names one thing their institution does well. Two minutes, no discussion.</p><p>2.  The group agrees the single biggest blockage. It must be a sentence, not a word — &quot;capacity&quot; and &quot;political will&quot; are categories, not blockages. Say what specifically does not happen.</p><p>3.  Place that blockage at the stage of the policy cycle where it bites.</p><p>4.  Complete the card below and be ready to report in one minute.</p><p>Group card</p><div class=\"table-scroll\"><table><tr><th></th><th></th></tr><tr><td>One thing our institution does well</td><td></td></tr><tr><td>The single biggest blockage<br>(a sentence)</td><td></td></tr><tr><td>Where it bites in the policy cycle<br>(agenda setting / formulation / decision /<br>implementation / monitoring)</td><td></td></tr><tr><td>Who could remove it</td><td></td></tr></table></div><p>Facilitators collect these cards. They are used to form the working-group themes on day three.</p>","sessions":[1]},{"id":"A3519987-h10","workshop":"institutions","code":"A3519987","number":10,"title":"Register entry and indicator set","file":"downloads/A3519987/A3519987_H10.1_Register_and_indicator_set.docx","html":"<p>PARTICIPANT HANDOUT 10.1</p><p>Register entry and indicator set</p><p>Session 10 — Day three, 11:00–12:30   ·   20 minutes   ·   Same groups as Session 9</p><div class=\"table-scroll\"><table><tr><th>TASK    Enter your implementation framework into the register, then design the minimum indicator set your body would need to report annually.</th></tr></table></div><p>Step 1 — The register entry</p><div class=\"table-scroll\"><table><tr><th>Ref</th><th>Adopted (date and meeting)</th><th>The conclusion</th><th>Output</th><th>Owner (post)</th><th>Deadline</th><th>Indicator</th><th>Status</th><th>Last updated / by</th></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>Status values — use only these: not yet due  ·  on track  ·  delayed, new date agreed  ·  delayed, no new date  ·  blocked, reason recorded  ·  closed, delivered  ·  closed, superseded</p><p>Step 2 — The pre-meeting question</p><p>Write, in one sentence, the question the secretariat would put to the owner a week before the meeting. The owner must be able to answer it in one line.</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div><p>Step 3 — Four indicators</p><p>At least one process, one output, and one gender or inclusion indicator.</p><div class=\"table-scroll\"><table><tr><th></th><th>Type</th><th>Indicator</th><th>Source document</th><th>Who collects it</th><th>How often</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>Step 4 — The uncomfortable one</p><div class=\"table-scroll\"><table><tr><th>Which of your four would you least like to report honestly?</th><th>Did you keep it?</th><th>Why / why not</th></tr><tr><td></td><td>□ Yes   □ No</td><td></td></tr></table></div><p>An indicator that can never look bad is not measuring anything.</p>","sessions":[10]},{"id":"A3519987-h11","workshop":"institutions","code":"A3519987","number":11,"title":"Institutional diagnostic and reform pathway","file":"downloads/A3519987/A3519987_H11.1_Institutional_diagnostic_and_reform_pathway.docx","html":"<p>PARTICIPANT HANDOUT 11.1</p><p>Institutional diagnostic and reform pathway</p><p>Session 11 — Day three, 13:30–15:00   ·   20 minutes   ·   Four mixed tripartite groups</p><div class=\"table-scroll\"><table><tr><th>TASK    Diagnose the main cause of underperformance in the institution you know best, and sequence a realistic two-year reform pathway.</th></tr></table></div><p>Institution: ______________________________________________</p><p>The underperformance, in one sentence — what does not happen that should</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div><p>Step 1 — Diagnosis</p><div class=\"table-scroll\"><table><tr><th></th><th>Cause</th><th>Diagnostic question</th><th>Evidence for or against</th></tr><tr><td>□</td><td>Mandate</td><td>Has the body ever attempted this and been told it could not?</td><td></td></tr><tr><td>□</td><td>Capacity</td><td>Would more staff fix it, or would the same staff working differently fix it?</td><td></td></tr><tr><td>□</td><td>Procedure</td><td>Are the working methods wasting the mandate and capacity that exist?</td><td></td></tr><tr><td>□</td><td>Participation</td><td>Do those attending have authority to commit their organizations?</td><td></td></tr><tr><td>□</td><td>Political space</td><td>Is everything in place but the decisions not wanted?</td><td></td></tr></table></div><p>Step 2 — Practice changes that could start within three months</p><p>These need no instrument and, mostly, no decision beyond the secretariat and the chair.</p><div class=\"table-scroll\"><table><tr><th></th><th>Change</th><th>Who decides</th><th>Start by</th></tr><tr><td>1</td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td></tr></table></div><p>Step 3 — The one capacity request</p><div class=\"table-scroll\"><table><tr><th>What you would ask for</th><th>What record you would build first</th><th>When you would submit it</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Step 4 — The one instrument change, if any</p><div class=\"table-scroll\"><table><tr><th>What would change</th><th>What must be true before you propose it</th></tr><tr><td></td><td></td></tr></table></div><p>The survival test</p><p>“If the three of us in this room left tomorrow, would this still be happening in a year?”  If no, which rung of the ladder does it need to move up?</p><p>●  Secretariat practice — survives until the staff change</p><p>●  Written procedure note — survives a staff change if the note is found</p><p>●  Decision of the body, minuted — survives because it can be cited</p><p>●  Written into the rules of procedure — survives because changing it needs a decision</p>","sessions":[11]},{"id":"A3519987-h12","workshop":"institutions","code":"A3519987","number":12,"title":"Policy proposal and institutional action plan — drafting template","file":"downloads/A3519987/A3519987_H12_Proposal_and_action_plan_template.docx","html":"<p>PARTICIPANT HANDOUT 12</p><p>Policy proposal and institutional action plan — drafting template</p><p>Sessions 12 and 13 — Days three and four   ·   Working groups</p><div class=\"table-scroll\"><table><tr><th>THE QUALITY BAR    A post, not an institution. A date, not a duration. A cost and who bears it. A statement of reach. Practice, capacity and instrument separated. A first step inside three months.</th></tr></table></div><p>Group theme: ______________________________    Rapporteur: ____________________    Drafter: ____________________</p><p>The problem, in one sentence — agreed by all three constituencies in your group</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div><p>PART A — Institutional action plan</p><p>Draft this first. It is the part you control, and the part this room can respond to.</p><div class=\"table-scroll\"><table><tr><th></th><th>What</th><th>Who (post)</th><th>When</th><th>What it needs</th><th>How we will know</th><th>Practice / capacity / instrument</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>Item 1 must start within three months.</p><p>PART B — Policy proposal</p><div class=\"table-scroll\"><table><tr><th>Field</th><th>Your entry</th></tr><tr><td>The measure<br>Two sentences, without justification</td><td></td></tr><tr><td>Legal basis<br>The provision that permits it, or the amendment required</td><td></td></tr><tr><td>Responsible institution<br>Which body decides, and which implements — often different</td><td></td></tr><tr><td>Reach<br>Who this touches and who it does not; the informal share; any differential effect by sex</td><td></td></tr><tr><td>Coordination<br>Which other bodies must act, and the handover arrangement</td><td></td></tr><tr><td>Indicator<br>How anyone would know, in a year, whether this had an effect</td><td></td></tr></table></div><p>PART C — What we could not resolve</p><p>A documented disagreement and a documented unknown are legitimate outputs. Use these rather than spending the morning on an argument you will not settle.</p><div class=\"table-scroll\"><table><tr><th></th><th>Use this sentence</th></tr><tr><td>Contested point</td><td>&quot;The group did not reach agreement on X. The government members considered that […]; the worker members considered that […]. The group recommends that the body take this up at [meeting].&quot;</td></tr><tr><td>Unknown figure</td><td>&quot;The group was unable to establish [figure]. It recommends that the secretariat obtain this from [source] before the measure is costed.&quot;</td></tr><tr><td>No owner</td><td>&quot;No owner could be identified within the group. The group recommends that [body] designate an owner at its meeting of [date].&quot;</td></tr></table></div><p>Our entries</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr><tr><td></td></tr><tr><td></td></tr></table></div><p>PART D — What we are asking the plenary for</p><div class=\"table-scroll\"><table><tr><th></th><th>Option</th><th>Specifically</th></tr><tr><td>□</td><td>Endorsement — the room agrees this is worth taking forward</td><td></td></tr><tr><td>□</td><td>A specific commitment — a named person or institution agrees to do one thing</td><td></td></tr><tr><td>□</td><td>An answer — a factual or mandate question we could not settle</td><td></td></tr><tr><td>□</td><td>A decision on ownership — which body should hold this</td><td></td></tr></table></div><p>Asking for nothing is the default, and it is why most plenary presentations change nothing.</p>","sessions":[12]},{"id":"A3519987-h13","workshop":"institutions","code":"A3519987","number":13,"title":"Peer review sheet","file":"downloads/A3519987/A3519987_H13_Peer_review_sheet.docx","html":"<p>PARTICIPANT HANDOUT 13</p><p>Peer review sheet</p><p>Session 13 — Day four, 09:40–10:10   ·   30 minutes   ·   Each group reviews another group’s draft</p><p>Draft being reviewed — group: ____________________    Reviewing group: ____________________</p><div class=\"table-scroll\"><table><tr><th>HOW TO REVIEW    Write amendments, not observations. Mark one thing as the strongest part. Limit yourself to five findings, ranked.</th></tr></table></div><p>Feasibility and cost</p><div class=\"table-scroll\"><table><tr><th>Question</th><th>Finding</th><th>Your amendment</th></tr><tr><td>Can the named owner actually do this, with the authority they have?</td><td></td><td></td></tr><tr><td>Has the cost been stated, even approximately, with a source of funding?</td><td></td><td></td></tr><tr><td>Does the first step depend on anyone outside the group’s influence?</td><td></td><td></td></tr><tr><td>What would have to go wrong for this to fail, and is that addressed?</td><td></td><td></td></tr></table></div><p>Mandate and reach</p><div class=\"table-scroll\"><table><tr><th>Question</th><th>Finding</th><th>Your amendment</th></tr><tr><td>Is this within the mandate of the institution named, on a reading of its instrument?</td><td></td><td></td></tr><tr><td>If two bodies could claim it, does the proposal say which holds it?</td><td></td><td></td></tr><tr><td>Who does this reach, and who does it not reach?</td><td></td><td></td></tr><tr><td>Has the differential effect on women been stated, or recorded as none?</td><td></td><td></td></tr></table></div><p>Your five findings, ranked</p><div class=\"table-scroll\"><table><tr><th>Rank</th><th>Finding</th><th>The amendment we would make</th></tr><tr><td>1</td><td></td><td></td></tr><tr><td>2</td><td></td><td></td></tr><tr><td>3</td><td></td><td></td></tr><tr><td>4</td><td></td><td></td></tr><tr><td>5</td><td></td><td></td></tr></table></div><p>The strongest part of this draft, and why:</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div><p>Reviews that are only critical get discounted. Say what works.</p>","sessions":[13]},{"id":"A3519987-h14","workshop":"institutions","code":"A3519987","number":14,"title":"Plenary feedback criteria and commitment card","file":"downloads/A3519987/A3519987_H14_Plenary_feedback_and_commitment_card.docx","html":"<p>PARTICIPANT HANDOUT 14</p><p>Plenary feedback criteria and commitment card</p><p>Session 14 — Day four, 11:00–12:30   ·   All participants</p><p>Part 1 — Feedback criteria</p><p>Use these while each group presents. Note one answer per presentation.</p><div class=\"table-scroll\"><table><tr><th></th><th>Group 1</th><th>Group 2</th><th>Group 3</th><th>Group 4</th></tr><tr><td>Would this work in your institution? If not, what specifically would stop it?</td><td></td><td></td><td></td><td></td></tr><tr><td>Is the first step genuinely within the named owner’s control?</td><td></td><td></td><td></td><td></td></tr><tr><td>Who does this reach, and who does it miss?</td><td></td><td></td><td></td><td></td></tr><tr><td>What would you, personally or institutionally, have to do for this to succeed?</td><td></td><td></td><td></td><td></td></tr></table></div><p>The fourth question is the one that turns an audience into participants.</p><p>Part 2 — My 30-day commitment</p><div class=\"table-scroll\"><table><tr><th>THE RULE    It must be within your own authority. Not something you will propose — something you will do.</th></tr></table></div><div class=\"table-scroll\"><table><tr><th></th><th></th></tr><tr><td>Name</td><td></td></tr><tr><td>Institution and role</td><td></td></tr><tr><td>Within 30 days of returning, I will</td><td></td></tr><tr><td>By this date</td><td></td></tr><tr><td>I will know it is done when</td><td></td></tr></table></div><p>Keep this card. The facilitation team photographs them for the course record.</p><p>Examples at the right scale</p><p>●  &quot;I will ask, at the next meeting, who owns each conclusion we adopt — before we adopt it.&quot;</p><p>●  &quot;I will add a reach statement to our paper template and use it on the next paper I draft.&quot;</p><p>●  &quot;I will extract every conclusion from the last two years of minutes into a single register.&quot;</p><p>●  &quot;I will put our women’s committee on the circulation list for every paper we receive.&quot;</p>","sessions":[14]},{"id":"A3519987-h2","workshop":"institutions","code":"A3519987","number":2,"title":"Building the institutional map","file":"downloads/A3519987/A3519987_H2.1_Institutional_mapping_sheet.docx","html":"<p>PARTICIPANT HANDOUT 2.1</p><p>Building the institutional map</p><p>Session 2 — Day one, 11:00–12:30   ·   25 minutes   ·   Four mixed tripartite groups</p><div class=\"table-scroll\"><table><tr><th>TASK    Map the tripartite institutions that matter for your assigned policy area, and mark every point where responsibility passes from one body to another.</th></tr></table></div><p>Your policy area: ______________________________________________</p><p>1.  Place national bodies at the top of the A1 sheet, sectoral in the middle, thematic below.</p><p>2.  Complete the six questions for each body, using the table on this sheet.</p><p>3.  Draw an arrow wherever a decision or recommendation passes from one body to another.</p><p>4.  Mark each arrow SOLID if a written rule governs it, DASHED if it depends on practice or personal contact.</p><p>5.  Circle every point where two bodies could both claim the same question.</p><p>Leave a blank and write a question mark where the group does not know. A documented gap is worth more than a confident guess.</p><p>The six questions</p><div class=\"table-scroll\"><table><tr><th></th><th>Body 1</th><th>Body 2</th><th>Body 3</th></tr><tr><td>1  Legal basis<br>Which statute, rule or notification creates it, and what does it require?</td><td></td><td></td><td></td></tr><tr><td>2  Composition<br>How many from each constituency, appointed by whom, for how long, quorum?</td><td></td><td></td><td></td></tr><tr><td>3  Mandate<br>What may it decide, what may it only recommend, and to whom?</td><td></td><td></td><td></td></tr><tr><td>4  Meeting rhythm<br>Required frequency  /  actual frequency in the last two years</td><td></td><td></td><td></td></tr><tr><td>5  Secretariat<br>Who services it, dedicated or seconded, and where do they sit?</td><td></td><td></td><td></td></tr><tr><td>6  Output route<br>Where do its conclusions go, who must respond, within what period?</td><td></td><td></td><td></td></tr></table></div>","sessions":[2]},{"id":"A3519987-h3","workshop":"institutions","code":"A3519987","number":3,"title":"The coordination protocol — drafting template","file":"downloads/A3519987/A3519987_H3.1_Coordination_protocol_template.docx","html":"<p>PARTICIPANT HANDOUT 3.1</p><p>The coordination protocol — drafting template</p><p>Session 3 — Day one, 13:30–15:00   ·   30 minutes   ·   Four mixed tripartite groups</p><div class=\"table-scroll\"><table><tr><th>TASK    Draft a working protocol between the National Social Dialogue Forum, the NTCC and the sectoral bodies, covering division of labour, referral and information flow.</th></tr></table></div><p>The test to draft against</p><p>“A constituent organization should be able to say, without asking anyone, which body is handling a given question today and when it will be decided.”</p><p>Write numbers, not adjectives. &quot;Within ten working days&quot; — not &quot;promptly&quot;. &quot;The body meeting soonest&quot; — not &quot;as appropriate&quot;.</p><p>Clause 1 — Basis for the division of labour</p><p>Tick one, then write one sentence saying why.</p><div class=\"table-scroll\"><table><tr><th></th><th>Basis</th><th>Why this one</th></tr><tr><td>□</td><td>By subject — each body takes defined subjects</td><td></td></tr><tr><td>□</td><td>By function — one consults where the law requires it, the other convenes and builds evidence</td><td></td></tr><tr><td>□</td><td>By stage — each body owns a distinct stage of the policy cycle</td><td></td></tr></table></div><p>Clause 2 — Referral</p><div class=\"table-scroll\"><table><tr><th>Element</th><th>Your rule</th></tr><tr><td>Default<br>Which body receives a new question first, absent agreement otherwise</td><td></td></tr><tr><td>Trigger<br>What facts move a question from one body to the other</td><td></td></tr><tr><td>Timing<br>How long before referral becomes automatic</td><td></td></tr><tr><td>Record<br>What travels with the question — file, minutes, recorded positions, dissent, or conclusion only</td><td></td></tr><tr><td>Tie-break<br>Who decides when both bodies claim a question, and on what basis</td><td></td></tr></table></div><p>Clause 3 — Information flow</p><div class=\"table-scroll\"><table><tr><th>Rule</th><th>Your wording (include the number of days)</th></tr><tr><td>Exchange of agendas</td><td></td></tr><tr><td>Exchange of adopted conclusions</td><td></td></tr><tr><td>Shared forward calendar</td><td></td></tr><tr><td>Shared register of live questions</td><td></td></tr></table></div><p>Clause 4 — Downward coordination</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr><tr><td></td></tr></table></div><p>Clause 5 — Publication</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div><p>Final check</p><div class=\"table-scroll\"><table><tr><th>Question</th><th>Yes</th><th>No</th></tr><tr><td>Could a constituent organization apply this without asking anyone?</td><td></td><td></td></tr><tr><td>Does every clause contain a number rather than an adjective?</td><td></td><td></td></tr><tr><td>Which clauses need an instrument, and which could start next month?</td><td></td><td></td></tr></table></div>","sessions":[3]},{"id":"A3519987-h4","workshop":"institutions","code":"A3519987","number":4,"title":"Comparative case notes","file":"downloads/A3519987/A3519987_H4_Comparative_case_notes.docx","html":"<p>PARTICIPANT HANDOUT 4</p><p>Comparative case notes</p><p>Session 4 — Day one, 15:30–16:30   ·   Reference material</p><p>Read these alongside the session. They are summaries of structural patterns, not full country descriptions — the purpose is to compare designs and the conditions they depend on.</p><p>Case A — A statutory council with standing chambers</p><div class=\"table-scroll\"><table><tr><th>Design</th><th>What it depends on, or what it shows</th></tr><tr><td>• Established by its own Act of Parliament, with a mandate to consider significant labour market and socio-economic policy before it goes to Parliament<br>• Four constituencies: government, business, labour, and a community constituency<br>• Work divided across standing chambers, so several questions proceed in parallel<br>• A permanent executive director and a dedicated professional secretariat</td><td>• A statutory obligation on government to table policy there — without it, attendance decays<br>• Social partners with the technical capacity to engage on economic, not only labour, policy<br>• A funded secretariat able to commission and challenge analysis<br>• Acceptance that a fourth, non-social-partner constituency sits at the table</td></tr></table></div><p>Case B — An advisory council with independent members</p><div class=\"table-scroll\"><table><tr><th>Design</th><th>What it depends on, or what it shows</th></tr><tr><td>• A national advisory council on social and economic policy; employers, trade unions and independent members appointed for their expertise<br>• Advice is published, reasoned and public, which creates its own pressure to respond<br>• A separate bipartite body handles employer–union agreements, keeping the functions distinct<br>• Long-horizon work — questions are taken up years before they become decisions</td><td>• A tradition of reasoned consensus rather than positional bargaining<br>• Independent members who are genuinely independent and publicly credible<br>• Patience — the value shows over years, not within a political cycle<br>• A clear separation between the advisory function and collective bargaining</td></tr></table></div><p>Case C — A lean body in a lower-income setting</p><div class=\"table-scroll\"><table><tr><th>Design</th><th>What it depends on, or what it shows</th></tr><tr><td>• A small national tripartite body with a narrow, clearly defined remit<br>• A short standing agenda — a handful of questions carried across meetings until resolved<br>• A secretariat of two or three, supplemented by technical support from the ILO and from the constituent organizations<br>• Sectoral committees that report in on a fixed cycle</td><td>• A narrow remit done consistently builds more credibility than a broad remit done occasionally<br>• Carrying questions across meetings is a cheap substitute for a large secretariat<br>• Technical capacity can be borrowed; the capacity to commission and judge it cannot<br>• A fixed reporting cycle from sectoral bodies solves downward coordination with no new structure</td></tr></table></div><p>Exercise 4.1 — Testing your protocol against the cases</p><div class=\"table-scroll\"><table><tr><th>TASK    Take the protocol your group drafted before the break and test it against the three patterns and three cautions.</th></tr></table></div><div class=\"table-scroll\"><table><tr><th>Test</th><th>What your protocol says</th><th>Amendment</th></tr><tr><td>Does anything in it create an obligation to come, or does it rely on goodwill?</td><td></td><td></td></tr><tr><td>Does it assume secretariat capacity that exists, or capacity that must be built first?</td><td></td><td></td></tr><tr><td>Does it say anything about publishing the record?</td><td></td><td></td></tr><tr><td>Which single clause is most likely to fail because an enabling condition is missing?</td><td></td><td></td></tr></table></div>","sessions":[4]},{"id":"A3519987-h5","workshop":"institutions","code":"A3519987","number":5,"title":"Evidence pack and policy options note","file":"downloads/A3519987/A3519987_H5.1_Evidence_pack_and_options_note.docx","html":"<p>PARTICIPANT HANDOUT 5.1</p><p>Evidence pack and policy options note</p><p>Session 5 — Day two, 09:00–10:30   ·   20 minutes   ·   Four mixed tripartite groups</p><p>TRAINING MATERIAL — SIMULATED EVIDENCE. The sources below were written for this exercise. The figures are illustrative and must not be cited outside the training room.</p><div class=\"table-scroll\"><table><tr><th>THE QUESTION    The body has been asked to advise on extending occupational safety and health requirements to establishments below the current size threshold.</th></tr></table></div><p>Four sources</p><p>Source A  —  Ministry press release, issued last month</p><p>&quot;The Government is firmly committed to protecting every worker. Compliance with safety requirements has improved substantially in recent years and the inspection system is now among the most responsive in the region. Any extension of requirements will be introduced in a manner that does not burden small enterprises.&quot;<br><br>No method, sample or data source is stated. No figures are given.</p><p>Source B  —  Survey by a national workers’ organization, fieldwork conducted this year</p><p>Reports that 62 per cent of workers surveyed in establishments below the threshold had received no safety training, and that 1 in 4 reported an injury or near-miss in the past twelve months.<br><br>Method: self-completed questionnaire distributed through member organizations; 1,840 responses; establishments self-identified as below the threshold; responses concentrated in two divisions.</p><p>Source C  —  Employers’ federation study, published this year, fieldwork conducted four years ago</p><p>Estimates the average cost of compliance for a small establishment at an amount equivalent to 3.4 per cent of annual turnover, and concludes that extension would be &quot;economically unviable&quot; for the majority of units below the threshold.<br><br>Method: structured interviews with 95 member enterprises; &quot;small establishment&quot; defined by turnover, not by employee numbers; costs expressed in prices of the fieldwork year.</p><p>Source D  —  Official labour inspection statistics, most recent published series</p><p>Of establishments inspected in the reporting period, 41 per cent were recorded as fully compliant with existing requirements. Establishments below the size threshold are not included in the routine inspection programme and therefore do not appear in the series.<br><br>Method: administrative records of completed inspections. Coverage: registered establishments above the threshold only. Collection period stated in the publication.</p><p>Step 1 — Vet the sources</p><p>Apply the four tests and mark each source usable, usable with a caveat, or not usable.</p><div class=\"table-scroll\"><table><tr><th></th><th>Provenance</th><th>Method</th><th>Currency</th><th>Corroboration</th><th>Verdict</th></tr><tr><td>Source A</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Source B</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Source C</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Source D</td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>Step 2 — Factual summary</p><p>Maximum 150 words, using only what survived vetting. No emotive or evaluative language.</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr><tr><td></td></tr><tr><td></td></tr><tr><td></td></tr><tr><td></td></tr><tr><td></td></tr></table></div><p>Step 3 — Policy options</p><p>Two or three distinct options. They must rest on different judgements, not on one judgement at three settings.</p><div class=\"table-scroll\"><table><tr><th></th><th>The option</th><th>Indicative cost and who bears it</th><th>Responsible institution</th></tr><tr><td>A</td><td></td><td></td><td></td></tr><tr><td>B</td><td></td><td></td><td></td></tr><tr><td>C</td><td></td><td></td><td></td></tr></table></div><p>Step 4 — What is contested, and what is unknown</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr><tr><td></td></tr><tr><td></td></tr></table></div><p>Step 5 — Read your summary aloud in the group and strike every word that signals a preference. How many did you strike? ________</p>","sessions":[5]},{"id":"A3519987-h6","workshop":"institutions","code":"A3519987","number":6,"title":"Gender-responsiveness audit grid","file":"downloads/A3519987/A3519987_H6.1_Gender_responsiveness_audit_grid.docx","html":"<p>PARTICIPANT HANDOUT 6.1</p><p>Gender-responsiveness audit grid</p><p>Session 6 — Day two, 11:00–12:30   ·   25 minutes   ·   Auditing a neighbouring group’s options note</p><div class=\"table-scroll\"><table><tr><th>TASK    Audit the options note drafted by the group to your right, and return it with specific drafted amendments — not general observations.</th></tr></table></div><p>Note being audited — group: ____________________    Auditing group: ____________________</p><div class=\"table-scroll\"><table><tr><th>Question</th><th>What the note says</th><th>Your amendment (write the wording)</th></tr><tr><td>1  Affected population<br>Does it state who is affected, and the share who are women?</td><td></td><td></td></tr><tr><td>2  Disaggregated evidence<br>Are the sources cited disaggregated by sex? Did they check, or assume?</td><td></td><td></td></tr><tr><td>3  Differential effect<br>For each option: is the effect on women different in size, different in kind, or not at all?</td><td></td><td></td></tr><tr><td>4  Delivery reach<br>Timing, location, language, literacy, cost of access, who holds the information</td><td></td><td></td></tr><tr><td>5  Monitoring trigger<br>Is monitoring disaggregated, and does a gap trigger anything?</td><td></td><td></td></tr></table></div><p>The add-on test</p><p>“If the gender paragraph were deleted from this proposal, would any other part of it change?”</p><div class=\"table-scroll\"><table><tr><th>Before your amendments</th><th>After your amendments</th></tr><tr><td>□ Yes — it is integrated<br>□ No — it is an add-on</td><td>□ Yes — it is integrated<br>□ No — it is an add-on</td></tr></table></div><p>Which single amendment, if adopted, would change the decision rather than just the document?</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr><tr><td></td></tr></table></div>","sessions":[6]},{"id":"A3519987-h7","workshop":"institutions","code":"A3519987","number":7,"title":"Representation gap diagnostic","file":"downloads/A3519987/A3519987_H7.1_Representation_gap_diagnostic.docx","html":"<p>PARTICIPANT HANDOUT 7.1</p><p>Representation gap diagnostic</p><p>Session 7 — Day two, 13:30–15:00   ·   25 minutes   ·   Four mixed tripartite groups</p><div class=\"table-scroll\"><table><tr><th>TASK    Estimate who your institution’s decisions actually reach, and identify the two most promising entry points for extending that reach.</th></tr></table></div><p>Policy area: ______________________________    Institution: ______________________________</p><p>Step 1 — Reach by population group</p><div class=\"table-scroll\"><table><tr><th>Population group</th><th>Roughly what share of the affected population?</th><th>Reached through representation?</th><th>Reached through regulation?</th><th>Reached by nobody?</th></tr><tr><td>Formal employees in formal units</td><td></td><td></td><td></td><td></td></tr><tr><td>Informal employment inside formal units<br>(subcontracted, casual, through intermediaries)</td><td></td><td></td><td></td><td></td></tr><tr><td>Workers in informal units</td><td></td><td></td><td></td><td></td></tr><tr><td>Own-account and contributing family workers</td><td></td><td></td><td></td><td></td></tr></table></div><p>Step 2 — The reach test, applied to a real measure</p><p>Choose one measure your body has adopted in the last two years: ______________________________________________</p><div class=\"table-scroll\"><table><tr><th>Question</th><th>Yes</th><th>No</th><th>What follows</th></tr><tr><td>Does it depend on the worker having a written contract?</td><td></td><td></td><td></td></tr><tr><td>Does it depend on there being a registered employer?</td><td></td><td></td><td></td></tr><tr><td>Does it depend on a fixed workplace?</td><td></td><td></td><td></td></tr><tr><td>Does it depend on the worker initiating a claim, and bearing the cost and risk?</td><td></td><td></td><td></td></tr><tr><td>Does it reach people through a channel they already use?</td><td></td><td></td><td></td></tr><tr><td>Does the administrative burden sit with the party best able to carry it?</td><td></td><td></td><td></td></tr></table></div><p>If the answer to the first four is yes, the measure reaches the formal economy and stops.</p><p>Step 3 — Two entry points</p><div class=\"table-scroll\"><table><tr><th>Entry point</th><th>First step</th><th>Who takes it</th><th>By when</th></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></table></div><p>Step 4 — The one rule in our own procedures that excludes by construction:</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div>","sessions":[7]},{"id":"A3519987-h8","workshop":"institutions","code":"A3519987","number":8,"title":"Designing a participation mechanism","file":"downloads/A3519987/A3519987_H8.1_Mechanism_design_sheet.docx","html":"<p>PARTICIPANT HANDOUT 8.1</p><p>Designing a participation mechanism</p><p>Session 8 — Day two, 15:30–16:30   ·   12 minutes   ·   Same groups</p><div class=\"table-scroll\"><table><tr><th>TASK    Design one mechanism for the gap your group identified, specified well enough to put to a board.</th></tr></table></div><p>1  The gap, in one sentence — whose voices are not heard, on what questions</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div><p>2  The mechanism</p><div class=\"table-scroll\"><table><tr><th></th><th>Mechanism</th><th>Why this one and not a heavier or lighter one</th></tr><tr><td>□</td><td>Technical contribution on a specific item — no standing, no continuing status</td><td></td></tr><tr><td>□</td><td>Observer status — attends, may speak, no vote, does not count to quorum</td><td></td></tr><tr><td>□</td><td>Consultative panel or sub-committee — standing, own membership rules</td><td></td></tr><tr><td>□</td><td>Seat on the body — full membership; requires amendment of the instrument</td><td></td></tr></table></div><p>3  Representativeness criteria — three to five, each verifiable by someone outside this group</p><p>&quot;Genuinely representative&quot; is not a criterion. A membership register, a constitution, elections held within a stated period, years since establishment — those are criteria.</p><div class=\"table-scroll\"><table><tr><th></th><th>Criterion</th><th>How it would be verified</th></tr><tr><td>1</td><td></td><td></td></tr><tr><td>2</td><td></td><td></td></tr><tr><td>3</td><td></td><td></td></tr><tr><td>4</td><td></td><td></td></tr><tr><td>5</td><td></td><td></td></tr></table></div><p>4  The bounded role</p><div class=\"table-scroll\"><table><tr><th>They MAY</th><th>They MAY NOT</th></tr><tr><td></td><td></td></tr></table></div><p>5  The review point</p><div class=\"table-scroll\"><table><tr><th>Review date</th><th>Criteria the review will apply</th><th>What happens if it has not worked</th></tr><tr><td></td><td></td><td></td></tr></table></div>","sessions":[8]},{"id":"A3519987-h9","workshop":"institutions","code":"A3519987","number":9,"title":"Conclusions for conversion, and the implementation framework","file":"downloads/A3519987/A3519987_H9.1_Conclusions_and_implementation_framework.docx","html":"<p>PARTICIPANT HANDOUT 9.1</p><p>Conclusions for conversion, and the implementation framework</p><p>Session 9 — Day three, 09:00–10:30   ·   22 minutes   ·   Four mixed tripartite groups</p><p>TRAINING MATERIAL — SIMULATED CONCLUSIONS. These were written for this exercise. They are deliberately vague, in the way real conclusions often are.</p><div class=\"table-scroll\"><table><tr><th>TASK    Take the conclusion assigned to your group and convert it into a full implementation framework.</th></tr></table></div><p>The four conclusions</p><div class=\"table-scroll\"><table><tr><th>Group</th><th>The conclusion, as adopted</th></tr><tr><td>1</td><td>&quot;The Council agreed that the current arrangements for consulting sectoral bodies should be reviewed with a view to making them more systematic.&quot;</td></tr><tr><td>2</td><td>&quot;The Council noted with concern the delays in responding to its recommendations and agreed that this matter should be taken forward with the relevant authorities.&quot;</td></tr><tr><td>3</td><td>&quot;The Council agreed that the Labour Act should be amended to extend coverage of the provisions in question, and requested that this be pursued.&quot;</td></tr><tr><td>4</td><td>&quot;The Council agreed that better data on the matters under discussion would assist its work, and that steps should be taken to obtain it.&quot;</td></tr></table></div><p>Step 1 — Classify</p><div class=\"table-scroll\"><table><tr><th></th><th>Category</th><th>What it means for you</th></tr><tr><td>□</td><td>Within the body’s own control</td><td>Can be committed to. Should never slip</td></tr><tr><td>□</td><td>Within a constituent’s control</td><td>Can be committed to only if that constituent agrees at the table</td></tr><tr><td>□</td><td>Outside everyone’s control</td><td>Cannot be recorded as a commitment — record it as a recommendation plus a tracking item</td></tr></table></div><p>Step 2 — The first commitment only</p><p>The next concrete step, not the destination. Draft terms of reference, not a reformed system.</p><div class=\"table-scroll\"><table><tr><th>Element</th><th>Your entry</th></tr><tr><td>Output<br>What specific, verifiable thing will exist that does not exist now</td><td></td></tr><tr><td>Owner<br>A named post, not an institution. If you cannot telephone it, it is not an owner</td><td></td></tr><tr><td>Deadline<br>A date, not a duration</td><td></td></tr><tr><td>Resource<br>Staff days, money, and whose approval is needed — and has it been checked?</td><td></td></tr><tr><td>Indicator<br>How the body will know, at its next meeting, that this happened</td><td></td></tr></table></div><p>Step 3 — Coordination and handover</p><div class=\"table-scroll\"><table><tr><th>Question</th><th>Your answer</th></tr><tr><td>Which other institutions must act, and were they in the room?</td><td></td></tr><tr><td>Which sectoral or thematic body picks this up, and at which meeting?</td><td></td></tr><tr><td>If both the Forum and the NTCC have an interest, which holds it — under your Monday protocol?</td><td></td></tr><tr><td>Who transmits it, to whom, within how many days?</td><td></td></tr></table></div><p>Step 4 — The Monday-morning test</p><p>“Can the person who has to do this hear about it from the minutes alone, and know exactly what to do on Monday morning?”</p><p>Read your framework aloud as if you were the owner reading the minute. What was missing?</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr><tr><td></td></tr></table></div><p>If your conclusion is in category three</p><p>It cannot be recorded as a commitment. Complete this instead.</p><div class=\"table-scroll\"><table><tr><th>Element</th><th>Your entry</th></tr><tr><td>The recommendation, clearly labelled as such</td><td></td></tr><tr><td>The body it is addressed to, by name</td><td></td></tr><tr><td>The commitment within your control: who transmits it, to whom, by when</td><td></td></tr><tr><td>The tracking item: what the secretariat reports at each meeting</td><td></td></tr><tr><td>What the body does if no response comes after a stated period</td><td></td></tr></table></div>","sessions":[9]},{"id":"A3519988-h1","workshop":"secretariats","code":"A3519988","number":1,"title":"Self-assessment and your outcomes","file":"downloads/A3519988/A3519988_H1_Self_assessment_and_outcomes.docx","html":"<p>PARTICIPANT HANDOUT 1</p><p>Self-assessment and your outcomes</p><p>Session 1 — Day one, 09:00–10:30   ·   Individually</p><p>Part 1 — Secretariat competencies</p><p>For your own use. Nobody collects this. Mark where you are now, honestly — the second column tells you which modules to pay most attention to.</p><div class=\"table-scroll\"><table><tr><th>Competency</th><th>Not yet</th><th>Developing</th><th>Confident</th><th>Covered in</th></tr><tr><td>Rules of procedure, quorum, notice periods</td><td></td><td></td><td></td><td>Modules 3 and 6</td></tr><tr><td>Constructing an agenda that states each item’s purpose</td><td></td><td></td><td></td><td>Modules 3 and 6</td></tr><tr><td>Drafting minutes as decisions and actions</td><td></td><td></td><td></td><td>Module 4</td></tr><tr><td>Producing an action sheet and tracking it</td><td></td><td></td><td></td><td>Modules 4 and 9</td></tr><tr><td>Reading and vetting evidence</td><td></td><td></td><td></td><td>Module 8</td></tr><tr><td>Drafting a neutral briefing note</td><td></td><td></td><td></td><td>Modules 5 and 8</td></tr><tr><td>Preparing and defending a budget</td><td></td><td></td><td></td><td>Module 7</td></tr><tr><td>Handling a private approach from one party</td><td></td><td></td><td></td><td>Modules 2 and 6</td></tr><tr><td>Reframing a charged statement</td><td></td><td></td><td></td><td>Module 5</td></tr><tr><td>Records, indexing and institutional memory</td><td></td><td></td><td></td><td>Modules 4 and 10</td></tr></table></div><p>Part 2 — Your outcomes</p><p>Three things you want to be able to do differently when you return to your institution. Specific to your own job, not to the institution in general. We return to this list on Sunday.</p><div class=\"table-scroll\"><table><tr><th></th><th>By the end of these three days I want to be able to…</th></tr><tr><td>1</td><td></td></tr><tr><td>2</td><td></td></tr><tr><td>3</td><td></td></tr></table></div><p>Part 3 — Running list</p><p>Keep this open for all three days. Every time a module produces something you could adopt, write it here. On Sunday this becomes your 30-day plan — and the people who kept a list arrive with material while everyone else is trying to remember three days.</p><div class=\"table-scroll\"><table><tr><th>Module</th><th>Something I could adopt</th><th>Needs whose agreement?</th></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr></table></div>","sessions":[1]},{"id":"A3519988-h2","workshop":"secretariats","code":"A3519988","number":2,"title":"Conduct and ethics scenarios","file":"downloads/A3519988/A3519988_H2.1_Conduct_and_ethics_scenarios.docx","html":"<p>PARTICIPANT HANDOUT 2.1</p><p>Conduct and ethics scenarios</p><p>Session 2 — Day one, 11:00–12:30   ·   25 minutes   ·   Four groups, two scenarios each</p><div class=\"table-scroll\"><table><tr><th>TASK    Decide how you would respond in the moment, then agree the rule — written in advance — that would have removed the judgement from the moment.</th></tr></table></div><p>None of these involves anybody behaving badly. Most involve somebody trying to be helpful.</p><p>Scenario 1</p><p>A member asks you to check a figure in their submission before it goes in. You would do the same for any member. Nobody else knows you did it.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 2</p><p>A party raises a substantive point with you in the corridor before the meeting. You respond thoughtfully. The other two parties were not present.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 3</p><p>In drafting the minutes you soften a sharp exchange because it reads badly. The party whose objection was softened reads the draft.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 4</p><p>A government official hands you a memo with talking points for the briefing note, marked &quot;not to be shared with the other social partners&quot;.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 5</p><p>Owing to a printing error, one party’s documents will arrive a day later than the others’. You have been asked to send what is ready.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 6</p><p>A party asks you to place their item first on the agenda, because their representative has to leave early.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 7</p><p>A journalist telephones to ask what was decided at yesterday’s meeting. Nothing has been published.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 8</p><p>A senior official asks you to leave an item off the agenda entirely, saying that &quot;the Minister would prefer it not be discussed at this stage&quot;.</p><div class=\"table-scroll\"><table><tr><th>What you say or do, there and then</th><th>Which party is watching, and what they conclude</th><th>The rule, written in advance (one sentence)</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Two tests for a difficult moment</p><div class=\"table-scroll\"><table><tr><th>The mandate test</th><th>The visibility test</th></tr><tr><td>Is there a conflict here, or can the secretariat act in congruence with the oath of office and the standard expected of the role?<br><br>If the instrument or the rules of procedure address this, that settles it.<br><br>If they do not: does the action advance the body’s function, or one party’s position?</td><td>Would I be comfortable if my children, my parents, or those close to me knew what I am doing?<br><br>Would I be comfortable if the other two parties learned of this tomorrow?<br><br>If the answer to either is no, the action is wrong regardless of its justification.</td></tr></table></div><p>Minimum standards of conduct — our draft</p><p>Assembled from the rules this room has just written.</p><div class=\"table-scroll\"><table><tr><th></th><th>Standard</th></tr><tr><td>1</td><td></td></tr><tr><td>2</td><td></td></tr><tr><td>3</td><td></td></tr><tr><td>4</td><td></td></tr><tr><td>5</td><td></td></tr><tr><td>6</td><td></td></tr><tr><td>7</td><td></td></tr></table></div>","sessions":[2]},{"id":"A3519988-h3","workshop":"secretariats","code":"A3519988","number":3,"title":"Meeting scenarios, agenda and notice","file":"downloads/A3519988/A3519988_H3.1_Meeting_scenarios_agenda_and_notice.docx","html":"<p>PARTICIPANT HANDOUT 3.1</p><p>Meeting scenarios, agenda and notice</p><p>Session 3 — Day one, 13:30–15:00   ·   30 minutes — 10 preparation, 5 setup, 15 role play   ·   Four groups</p><p>TRAINING MATERIAL — SIMULATED SCENARIOS, written for this exercise.</p><div class=\"table-scroll\"><table><tr><th>TASK    As the secretariat, prepare the agenda and the notice for your meeting, then present them to the chair for approval.</th></tr></table></div><p>Your scenario</p><div class=\"table-scroll\"><table><tr><th>Group</th><th>The meeting</th></tr><tr><td>1</td><td>An ordinary quarterly meeting. Six items have been submitted, one of them by a worker organization four days ago — after the submission deadline — on a dispute in a single enterprise. One item is a routine annual report. One concerns a draft rule on which the Ministry wants the body’s view before it goes forward.</td></tr><tr><td>2</td><td>An ordinary meeting at which the body must consider a proposal that both employer and worker members have already said publicly they oppose, for different reasons. Three other items are routine. The chair is new and has not previously chaired this body.</td></tr><tr><td>3</td><td>An extraordinary meeting called at ten days’ notice on a single urgent question. Two members have asked to add further items. The rules allow extraordinary meetings only on the business for which they were called.</td></tr><tr><td>4</td><td>An ordinary meeting where the main item is a technical proposal that none of the members has the expertise to assess. An external body has offered to present. Two other items are carried over from the last meeting, unreached.</td></tr></table></div><p>Step 1 — The agenda</p><div class=\"table-scroll\"><table><tr><th>No.</th><th>Item</th><th>Purpose<br>(information / discussion / decision)</th><th>Time</th><th>Paper</th><th>Draft conclusion attached?</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>Step 2 — The notice</p><div class=\"table-scroll\"><table><tr><th>Element</th><th>Your entry</th></tr><tr><td>Type of meeting, number and date</td><td></td></tr><tr><td>Date of dispatch, and days of notice given</td><td></td></tr><tr><td>Quorum required, and quorum by constituency</td><td></td></tr><tr><td>Venue, time and expected duration</td><td></td></tr><tr><td>Working documents enclosed (list by reference)</td><td></td></tr><tr><td>How and by when members may propose amendments to the agenda</td><td></td></tr></table></div><p>Step 3 — The chair’s review</p><p>The chair must challenge at least two items — on sequencing, on purpose, or on whether the item belongs at all.</p><div class=\"table-scroll\"><table><tr><th>What the chair challenged</th><th>Your justification — from the rules or from practice?</th><th>What you changed</th></tr><tr><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td></tr></table></div><p>Step 4 — Back in your own institution</p><p>One change you will make to your own agenda next week:</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div>","sessions":[3]},{"id":"A3519988-h4","workshop":"secretariats","code":"A3519988","number":4,"title":"The minutes audit","file":"downloads/A3519988/A3519988_H4.1_Minutes_audit_and_action_sheet.docx","html":"<p>PARTICIPANT HANDOUT 4.1</p><p>The minutes audit</p><p>Session 4 — Day one, 15:30–16:30   ·   12 minutes   ·   Four groups</p><p>TRAINING MATERIAL — SIMULATED MINUTES. Written for this exercise, and deliberately flawed. The institution, the people and the business are invented.</p><div class=\"table-scroll\"><table><tr><th>TASK    Mark every place where a decision is stated too vaguely to track, rewrite each one in the standard form, and extract the action sheet.</th></tr></table></div><p>Draft minutes for audit</p><p>NATIONAL CONSULTATIVE BODY — ORDINARY MEETING</p><p>Minutes of the meeting held on [date] at the Ministry conference room.</p><p>1.  Opening</p><p>The Chairperson welcomed members and thanked them for attending. Apologies were received from several members. The minutes of the previous meeting were adopted.</p><p>2.  Review of the grievance registration system</p><p>The worker representative expressed strong concern about the accessibility of the current registration system, noting that women workers in particular face difficulties. The employer representative responded that the system functions adequately and that further changes would create administrative burden. Various members expressed views. After extensive discussion it was agreed that the system needs to be reviewed to make it more accessible, especially for women workers, and that this matter will be followed up.</p><p>3.  Industrial dispute statistics</p><p>The Chairperson noted that the Committee had requested updated statistics at its last two meetings. The Government representative indicated that the Ministry will look into it and revert in due course.</p><p>4.  Draft rules on workplace committees</p><p>The draft rules were presented. Members discussed the proposed thresholds at length. The Committee noted with concern that the consultation period had been short. It was agreed that the draft rules are broadly acceptable subject to the comments made.</p><p>5.  Proposal for a technical sub-committee</p><p>A proposal was made to establish a technical sub-committee on occupational safety. There was general support for the idea. The Committee agreed that this should be taken forward as soon as possible.</p><p>6.  Any other business</p><p>A member raised the question of allowances for members travelling from outside the capital. After discussion the Chairperson said this would be examined. Another member raised the forthcoming International Labour Conference. The meeting closed at 4.45 p.m.</p><p>Step 1 — Rewrite the decisions</p><div class=\"table-scroll\"><table><tr><th>Item</th><th>What is wrong with it as drafted</th><th>Rewritten decision<br>(what, who, by when, how verified)</th></tr><tr><td>2</td><td></td><td></td></tr><tr><td>3</td><td></td><td></td></tr><tr><td>4</td><td></td><td></td></tr><tr><td>5</td><td></td><td></td></tr><tr><td>6</td><td></td><td></td></tr></table></div><p>Step 2 — The action sheet</p><div class=\"table-scroll\"><table><tr><th>No.</th><th>Task or output</th><th>Responsible (post)</th><th>Deadline</th><th>How it will be verified</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td></tr></table></div><p>Step 3 — Two further checks</p><div class=\"table-scroll\"><table><tr><th>Check</th><th>Your finding</th></tr><tr><td>Which paragraph reads as a decision but is actually a view? How would you relabel it?</td><td></td></tr><tr><td>Where has a disagreement been smoothed over? How would you record it honestly?</td><td></td></tr><tr><td>One thing the drafter did well</td><td></td></tr></table></div><p>Phrases to look for: &quot;it was agreed&quot; · &quot;noted with concern&quot; · &quot;will be followed up&quot; · &quot;various members expressed views&quot; · &quot;will look into it&quot; · &quot;in due course&quot; · &quot;as soon as possible&quot; · &quot;broadly acceptable&quot;</p>","sessions":[4]},{"id":"A3519988-h5","workshop":"secretariats","code":"A3519988","number":5,"title":"Reframing and neutral redrafting","file":"downloads/A3519988/A3519988_H5.1_Reframing_and_neutral_redrafting.docx","html":"<p>PARTICIPANT HANDOUT 5.1</p><p>Reframing and neutral redrafting</p><p>Session 5 — Day two, 09:00–10:30   ·   30 minutes across two drills   ·   Pairs, then four groups</p><p>Drill 1 — Reframing</p><div class=\"table-scroll\"><table><tr><th>TASK    Reframe each charged statement so that the substance survives and the attack does not.</th></tr></table></div><p>One of you reads the statement as it was made, with the tone it was made in. The other acknowledges, then reframes in one sentence. The reader then says whether they still recognize their own point. Swap for the next scenario.</p><p>A worked example</p><div class=\"table-scroll\"><table><tr><th></th><th></th></tr><tr><td>The statement</td><td>&quot;We are extremely disappointed because employers never listen to the workers’ side properly.&quot;</td></tr><tr><td>Acknowledge</td><td>&quot;I can hear that the worker members feel their contributions have not been taken up.&quot;</td></tr><tr><td>The content underneath</td><td>Worker proposals have not resulted in changes to outcomes.</td></tr><tr><td>Reframe</td><td>&quot;The worker members wish to raise whether their proposals have been reflected in the outcomes of recent meetings.&quot;</td></tr></table></div><p>A characterization of the other party has become a question about process — which is something the body can actually address.</p><p>Scenario 1</p><p>&quot;Every time we raise this, the Ministry tells us it is under consideration. That has been the answer for two years. Nobody intends to do anything.&quot;</p><div class=\"table-scroll\"><table><tr><th>Acknowledge</th><th>The content underneath</th><th>Your reframe</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 2</p><p>&quot;The employers only agreed to this because they know it will never be enforced. We are wasting our time here.&quot;</p><div class=\"table-scroll\"><table><tr><th>Acknowledge</th><th>The content underneath</th><th>Your reframe</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 3</p><p>&quot;These figures are from the unions, so obviously they are exaggerated. We cannot base a decision on that.&quot;</p><div class=\"table-scroll\"><table><tr><th>Acknowledge</th><th>The content underneath</th><th>Your reframe</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 4</p><p>&quot;If the Committee adopts this, our members will simply not comply, and then everyone will see how unrealistic it was.&quot;</p><div class=\"table-scroll\"><table><tr><th>Acknowledge</th><th>The content underneath</th><th>Your reframe</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Scenario 5</p><p>&quot;We were not consulted on this at all. It has clearly been decided somewhere else and we are being asked to rubber-stamp it.&quot;</p><div class=\"table-scroll\"><table><tr><th>Acknowledge</th><th>The content underneath</th><th>Your reframe</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Drill 2 — Neutral redrafting</p><div class=\"table-scroll\"><table><tr><th>TASK    Redraft each statement so that it is clear, concise, neutral and usable in a formal document.</th></tr></table></div><p>1.  Identify the words carrying the charge.</p><p>2.  Identify the factual content underneath — what is actually being asserted.</p><p>3.  Redraft, keeping the content and removing the charge.</p><p>4.  Check: would the party who said it accept your version as a fair record?</p><p>5.  Check: would the party it is aimed at accept it as a fair statement of the issue?</p><p>Statement 1</p><p>&quot;Since the unions keep delaying everything and sending incomplete stuff, we can’t move forward with the meeting.&quot;</p><div class=\"table-scroll\"><table><tr><th>The words carrying the charge</th><th>The factual content underneath</th><th>Your redraft</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Statement 2</p><p>&quot;We are extremely disappointed because employers never listen to the workers’ side properly.&quot;</p><div class=\"table-scroll\"><table><tr><th>The words carrying the charge</th><th>The factual content underneath</th><th>Your redraft</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Statement 3</p><p>&quot;Everyone agreed that something must be done soon to fix the issues with safety and other problems in the sector.&quot;</p><div class=\"table-scroll\"><table><tr><th>The words carrying the charge</th><th>The factual content underneath</th><th>Your redraft</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Statement 4</p><p>&quot;Government wants the unions to stop making unrealistic demands because it is slowing down progress.&quot;</p><div class=\"table-scroll\"><table><tr><th>The words carrying the charge</th><th>The factual content underneath</th><th>Your redraft</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>Statement 5</p><p>&quot;It has been noticed that people are not cooperating properly, so if this continues, we will take action.&quot;</p><div class=\"table-scroll\"><table><tr><th>The words carrying the charge</th><th>The factual content underneath</th><th>Your redraft</th></tr><tr><td></td><td></td><td></td></tr></table></div><p>One of these cannot be redrafted at all. Which, and why?</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr></table></div><p>An unattributed claim that &quot;everyone agreed&quot; cannot be made neutral — it can only be checked. Who agreed, and to what?</p><p>Drill 3 — Formal communication (take-away)</p><p>Eight situations the secretariat has to write about. For each, draft the opening sentence and note what must NOT appear.</p><div class=\"table-scroll\"><table><tr><th></th><th>Situation</th><th>Your opening sentence</th><th>What must not appear</th></tr><tr><td>1</td><td>Transmitting an adopted conclusion to a ministry</td><td></td><td></td></tr><tr><td>2</td><td>Informing a party that their item was received after the deadline</td><td></td><td></td></tr><tr><td>3</td><td>Declining a request to circulate a document from one party only</td><td></td><td></td></tr><tr><td>4</td><td>Recording a minority position at a party’s request</td><td></td><td></td></tr><tr><td>5</td><td>Requesting a status update on an overdue commitment</td><td></td><td></td></tr><tr><td>6</td><td>Inviting an external organization to contribute on one agenda item</td><td></td><td></td></tr><tr><td>7</td><td>Notifying members that a meeting is postponed</td><td></td><td></td></tr><tr><td>8</td><td>Responding to a member who disputes the record of what they said</td><td></td><td></td></tr></table></div><p>Structure: what this is about, in one sentence · what was decided or is requested, quoted exactly where it is a conclusion · what is required of the recipient and by when · who to contact and the reference. Nothing else.</p>","sessions":[5]},{"id":"A3519988-h6","workshop":"secretariats","code":"A3519988","number":6,"title":"Secretariat templates pack","file":"downloads/A3519988/A3519988_H6_Secretariat_templates_pack.docx","html":"<p>PARTICIPANT HANDOUT 6</p><p>Secretariat templates pack</p><p>For use during the course and afterwards   ·   All sessions</p><p>Seven templates, drawn from the modules. They are drafted to be used as they stand, or adapted to your own institution’s format. Nothing in them requires a decision beyond the secretariat and the chair.</p><p>1  Dispatch log</p><p>Module 6. One row per recipient, not one per dispatch — the point is to show on the face of it that all three parties were treated identically. Completed at the time, not reconstructed. Kept with the meeting file.</p><div class=\"table-scroll\"><table><tr><th>Date</th><th>Time</th><th>Document ref. and version</th><th>Recipient</th><th>Constituency</th><th>Channel</th><th>Acknowledged?</th><th>Sent by</th></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>2  Briefing note for the chair</p><p>Module 6. One page, issued two or three days before the meeting. It informs; it does not recommend an outcome. &quot;The Chair may wish to note that the rules require X&quot; is proper. &quot;The Chair should push for option B&quot; is not.</p><div class=\"table-scroll\"><table><tr><th>Agenda item</th><th>Decision sought</th><th>Positions likely to be taken, and where they differ</th><th>Procedural question likely to arise, and the rule that governs it</th><th>Suggested handling, and the fallback</th></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>3  Action sheet</p><p>Module 4 and Module 9. Produced immediately after the meeting, attached to the minutes, circulated with them. Open actions carry forward automatically, with their original date.</p><div class=\"table-scroll\"><table><tr><th>No.</th><th>Conclusion ref.</th><th>Task or output</th><th>Responsible (post)</th><th>Deadline</th><th>How it will be verified</th><th>Status</th><th>Carried from</th></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>4  Register of conclusions</p><p>Module 9. One continuous document. Nothing is ever deleted — items are closed with a reason. Tabled at every ordinary meeting as a standing item.</p><div class=\"table-scroll\"><table><tr><th>Res. no.</th><th>Adopted (date / meeting)</th><th>The conclusion</th><th>Owner (post)</th><th>Deadline</th><th>Indicator</th><th>Status</th><th>Last updated / by</th></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></table></div><p>Status values — use only these: not yet due  ·  on track  ·  delayed, new date agreed  ·  delayed, no new date  ·  blocked, reason recorded  ·  closed, delivered  ·  closed, superseded. Never &quot;ongoing&quot;.</p><p>5  Pre-meeting contact — standard wording</p><p>Module 9. Sent about one week before each meeting to every owner with an item falling due. The consequence in the third paragraph is what makes the system work.</p><div class=\"table-scroll\"><table><tr><th></th><th>Wording</th></tr><tr><td>The ask</td><td>The [body] adopted the following conclusion on [date]: &quot;[text of the conclusion]&quot;. You are recorded as the owner, with a deadline of [date]. Could you confirm the current status by [date, three working days from sending]?</td></tr><tr><td>The options</td><td>Please reply with one of the following: on track; delayed, new date [date]; delayed, no new date; blocked, because [reason]; or delivered, evidence attached.</td></tr><tr><td>The consequence</td><td>Items recorded as delayed with no new date, or blocked, are placed on the agenda of the next meeting for decision. All other items are noted without discussion.</td></tr></table></div><p>6  My 30-day plan</p><p>Module 11. Three quick wins. Each entirely within your own authority — not something you will propose, something you will do. One on protocol or documentation, one on technical support, one on follow-up.</p><div class=\"table-scroll\"><table><tr><th></th><th>Area</th><th>Specific — what exactly will be done</th><th>Measurable — how you will know it is done</th><th>Time-bound — date within 30 days</th></tr><tr><td>1</td><td>Protocol or documentation</td><td></td><td></td><td></td></tr><tr><td>2</td><td>Technical support</td><td></td><td></td><td></td></tr><tr><td>3</td><td>Follow-up</td><td></td><td></td><td></td></tr></table></div><p>Name: ______________________________    Institution: ______________________________    Date: ______________</p><p>7  Three-month institutional roadmap</p><p>Module 11. For the team, not the individual. Each month lays the foundation for the next. Consistent small improvements, sustained, change an institution; a single large effort, unsustained, changes nothing and exhausts the people who made it.</p><div class=\"table-scroll\"><table><tr><th>Month</th><th>Theme</th><th>Key team deliverable — the major, verifiable result</th><th>Which modules this applies</th><th>Who leads</th></tr><tr><td>1</td><td>Foundation and accountability</td><td></td><td></td><td></td></tr><tr><td>2</td><td>Technical excellence and neutrality</td><td></td><td></td><td></td></tr><tr><td>3</td><td>Sustainability and planning</td><td></td><td></td><td></td></tr></table></div><p>The rallying statement for your team — maximum fifty words, on why consistent small improvement beats a single push:</p><div class=\"table-scroll\"><table><tr><th></th></tr><tr><td></td></tr><tr><td></td></tr></table></div><p>Institution: ______________________________    Team members: ______________________________________________</p>","sessions":[6,7,8,9,10]}]};
